// The Python package's reference data, generated by xcl-python's release and
// fetched before each build (see scripts/fetch-python-reference.mjs).
import data from "../generated/python-reference.json";

export interface ReferenceParameter {
  name: string;
  type?: string;
  default?: string;
  description?: string;
}

export interface ReferenceReturns {
  type?: string;
  description?: string;
}

export interface ReferenceRaises {
  type: string;
  description?: string;
}

export interface ReferenceEntry {
  id: string;
  name: string;
  kind: string;
  label?: string;
  signature?: string;
  description: string;
  parameters?: ReferenceParameter[];
  returns?: ReferenceReturns;
  raises?: ReferenceRaises[];
  inheritedFrom?: string;
  members?: ReferenceEntry[];
}

export interface ReferenceSection {
  id: string;
  title: string;
  entries: ReferenceEntry[];
}

export interface Reference {
  schema: number;
  language: string;
  package: string;
  version: string;
  sections: ReferenceSection[];
}

export const reference = data as Reference;

const ids = new Set<string>();

function collect(entry: ReferenceEntry): void {
  ids.add(entry.id);
  entry.members?.forEach(collect);
}

reference.sections.forEach((section) => section.entries.forEach(collect));

/** Whether the reference has an entry with this full dotted name. */
export function hasEntry(id: string): boolean {
  return ids.has(id);
}
